строки?","options":["SELECT","COMMIT","CREATE","UPDATE"],"explanation":"UPDATE — наиболее точный ответ среди предложенных вариантов."},{"id":389,"text":"Какая команда удаляет строки по условию?","options":["DELETE","DROP","ALTER","REVOKE"],"explanation":"DELETE — наиболее точный ответ среди предложенных вариантов."},{"id":390,"text":"Какой запрос выбирает все строки и столбцы `products`?","options":["SHOW ALL products;","SELECT * FROM products;","GET * IN products;","SELECT products FROM *;"],"explanation":"SELECT * FROM products; — наиболее точный ответ среди предложенных вариантов."},{"id":391,"text":"Какой запрос добавит товар Book с ценой 500?","options":["SELECT 'Book', 500 FROM products;","UPDATE products SET ('Book', 500);","INSERT INTO products (name, price) VALUES ('Book', 500);","CREATE products VALUES ('Book', 500);"],"explanation":"INSERT INTO products (name, price) VALUES ('Book', 500); — наиболее точный ответ среди предложенных вариантов."},{"id":392,"text":"Какой запрос посчитает число заказов?","options":["SELECT SUM(*) FROM orders;","SELECT NUMBER FROM orders;","COUNT orders SELECT *;","SELECT COUNT(*) FROM orders;"],"explanation":"SELECT COUNT(*) FROM orders; — наиболее точный ответ среди предложенных вариантов."},{"id":393,"text":"Какое предложение задаёт условие отбора?","options":["WHERE","GROUP BY","ORDER BY","VALUES"],"explanation":"WHERE — наиболее точный ответ среди предложенных вариантов."},{"id":394,"text":"Какое предложение сортирует результат?","options":["GROUP BY","ORDER BY","VALUES","WHERE"],"explanation":"По указанным данным получается ответ: ORDER BY."},{"id":395,"text":"Какое предложение группирует строки?","options":["ORDER BY","SET","GROUP BY","WHERE"],"explanation":"GROUP BY — наиболее точный ответ среди предложенных вариантов."},{"id":396,"text":"Что означает C в ACID?","options":["Confidentiality","Concurrency","Control","Consistency"],"explanation":"Consistency — наиболее точный ответ среди предложенных вариантов."},{"id":397,"text":"Какая команда фиксирует транзакцию?","options":["COMMIT","DROP","GRANT","ROLLBACK"],"explanation":"COMMIT — наиболее точный ответ среди предложенных вариантов."},{"id":398,"text":"Какая команда отменяет неподтверждённые изменения?","options":["COMMIT","ROLLBACK","SELECT","CREATE"],"explanation":"ROLLBACK — наиболее точный ответ среди предложенных вариантов."},{"id":399,"text":"Какая команда создаёт представление?","options":["ALTER USER","CREATE INDEX","CREATE VIEW","CREATE DATABASE"],"explanation":"CREATE VIEW — наиболее точный ответ среди предложенных вариантов."},{"id":400,"text":"К какой группе относится CREATE TABLE?","options":["DCL","DML","TCL","DDL"],"explanation":"DDL — наиболее точный ответ среди предложенных вариантов."},{"id":401,"text":"К какой группе относится GRANT?","options":["DCL","DML","DDL","TCL"],"explanation":"DCL — наиболее точный ответ среди предложенных вариантов."},{"id":402,"text":"К какой группе относится COMMIT?","options":["DCL","TCL","DDL","DML"],"explanation":"TCL — наиболее точный ответ среди предложенных вариантов."},{"id":403,"text":"Что НЕ является стандартной группой SQL?","options":["Data Control Language","Data Definition Language","Data Destruction Language","Data Manipulation Language"],"explanation":"Data Destruction Language — наиболее точный ответ среди предложенных вариантов."},{"id":404,"text":"Как надёжнее защищаться от SQL-инъекции?","options":["Экранировать специальные символы вручную во всех строках","Проверять запрос только после выполнения в базе данных","Ограничиться проверкой длины пользовательского ввода","Использовать параметризованные запросы"],"explanation":"Использовать параметризованные запросы — наиболее точный ответ среди предложенных вариантов."},{"id":405,"text":"Для чего создают индекс?","options":["Для ускорения поиска по значениям","Для ускорения любых операций изменения данных","Для автоматического устранения дублирующихся строк","Для хранения резервной копии индексируемых столбцов"],"explanation":"Для ускорения поиска по значениям — наиболее точный ответ среди предложенных вариантов."},{"id":406,"text":"Что произойдёт при удалении столбца таблицы?","options":["Удалятся только значения, а определение столбца сохранится","Удалятся столбец и его значения","Удалятся строки, в которых поле имело значение NULL","Столбец будет скрыт, но останется доступен во всех запросах"],"explanation":"Удалятся столбец и его значения — наиболее точный ответ среди предложенных вариантов."},{"id":407,"text":"Что НЕ относится к стандартным группам SQL-команд?","options":["Data Manipulation Language","Transaction Control Language","Data Transfer Language","Data Definition Language"],"explanation":"Data Transfer Language — наиболее точный ответ среди предложенных вариантов."},{"id":408,"text":"Состояние защищённости информации и инфраструктуры от угроз — это:","options":["Целостность","Конфиденциальность","Доступность","Информационная безопасность"],"explanation":"Информационная безопасность — термин, соответствующий приведённому определению."},{"id":409,"text":"Доступность информации только уполномоченным субъектам — это:","options":["Конфиденциальность","Целостность","Доступность","Информационная безопасность"],"explanation":"Конфиденциальность — термин, соответствующий приведённому определению."},{"id":410,"text":"Сохранение правильности и неизменности от несанкционированных воздействий — это:","options":["Конфиденциальность","Целостность","Информационная безопасность","Доступность"],"explanation":"Целостность — термин, соответствующий приведённому определению."},{"id":411,"text":"Возможность получить информацию или услугу в требуемое время — это:","options":["Угроза","Целостность","Доступность","Конфиденциальность"],"explanation":"Доступность — термин, соответствующий приведённому определению."},{"id":412,"text":"Потенциальная причина нежелательного инцидента и ущерба — это:","options":["Доступность","Целостность","Уязвимость","Угроза"],"explanation":"Угроза — термин, соо